// HasRunTargets applies the HasEdge predicate on the "run_targets" edge.
func HasRunTargets() predicate.BenchmarkTarget {
	return predicate.BenchmarkTarget(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RunTargetsTable, RunTargetsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRunTargetsWith applies the HasEdge predicate on the "run_targets" edge with a given conditions (other predicates).
func HasRunTargetsWith(preds ...predicate.BenchmarkRunTarget) predicate.BenchmarkTarget {
	return predicate.BenchmarkTarget(func(s *sql.Selector) {
		step := newRunTargetsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchmarkTarget) predicate.BenchmarkTarget {
	return predicate.BenchmarkTarget(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchmarkTarget) predicate.BenchmarkTarget {
	return predicate.BenchmarkTarget(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchmarkTarget) predicate.BenchmarkTarget {
	return predicate.BenchmarkTarget(sql.NotPredicates(p))
}
